//! BuildKit gRPC message types — re-exported from the generated proto code.
//!
//! WHY: These are the real `buffa::Message` types generated by `buffa-build`
//! from the vendored BuildKit `.proto` files (see `build.rs` and
//! [`super::generated`]). They implement `buffa::Message + Serialize +
//! DeserializeOwned`, which is exactly what `foundation_connectrpc`'s
//! `ProcedureCodecs::defaults()` (proto + json) requires — so the BuildKit
//! client speaks real gRPC/proto to buildkitd, not a JSON approximation.
//!
//! WHAT: The Control-service request/response types for the RPCs we drive
//! (`Info`, `Solve`, `Status`). The full generated surface (LLB `Op` DAG,
//! worker records, source policy, …) lives under [`super::generated`].

pub use super::generated::moby::buildkit::v1::{
    BytesMessage, DiskUsageRequest, DiskUsageResponse, InfoRequest, InfoResponse,
    ListWorkersRequest, ListWorkersResponse, PruneRequest, SolveRequest, SolveResponse,
    StatusRequest, StatusResponse, UsageRecord,
};
